// Без входа nearby_live не отдаёт данных. Факт прогона 2026-10-28: 200 и []. Требование — «מחזיר תשובה רק למשתמש מאומת ומחובר»:
// проверяем, что данных нет (отказ 401/403 тоже подходит).
import { test, expect } from '../../fixtures';
import { setupMapUser, enableSharing, disableSharing, openMap } from './map-helpers';

test.describe('מיקום ומפה בזמן אמת', () => {
  test.describe.configure({ timeout: 240_000 }); // две роли + ожидание опроса карты у другого (#0f19c0)
  test('nearby_live без входа — пустой ответ, данных нет @iphone @data (#46db57)', async ({ asUser }) => {
    const free = await asUser('free');
    const guest = await asUser('guest');
    await setupMapUser(free, 'free');
    try {
      await enableSharing(free);
      // Берём настоящий запрос карты: адрес, тело и публичный apikey (без токена пользователя).
      const wait = free.waitForRequest((r) => r.url().includes('/rpc/nearby_live') && r.method() === 'POST');
      await free.reload();
      const req = await wait;
      const apikey = (await req.allHeaders())['apikey'];
      expect(apikey, 'apikey в запросе карты').toBeTruthy();

      const res = await guest.request.post(req.url(), {
        headers: { apikey, 'Content-Type': 'application/json' },
        data: req.postData() ?? '{}',
      });
      const text = await res.text();
      if (res.status() < 400) {
        expect(res.status()).toBe(200);
        expect(JSON.parse(text)).toEqual([]);
      } else {
        expect([401, 403]).toContain(res.status());
      }
    } finally {
      await openMap(free);
      await disableSharing(free);
    }
  });
});
